--
-- Table structure for table `inventory_daily_consumptions`
--

DROP TABLE IF EXISTS `inventory_daily_consumptions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventory_daily_consumptions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `business_id` bigint unsigned NOT NULL,
  `store_id` bigint unsigned NOT NULL,
  `item_id` bigint unsigned NOT NULL,
  `consumption_date` date NOT NULL,
  `quantity_suom` decimal(14,4) NOT NULL,
  `source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `recorded_by_user_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `inventory_daily_consumptions_unique` (`business_id`,`store_id`,`item_id`,`consumption_date`,`source`),
  KEY `inventory_daily_consumptions_store_id_foreign` (`store_id`),
  KEY `inventory_daily_consumptions_item_id_foreign` (`item_id`),
  KEY `inventory_daily_consumptions_recorded_by_user_id_foreign` (`recorded_by_user_id`),
  KEY `idc_business_consumption_date` (`business_id`,`consumption_date`),
  KEY `idc_business_store_date` (`business_id`,`store_id`,`consumption_date`),
  KEY `idc_business_item_date` (`business_id`,`item_id`,`consumption_date`),
  KEY `idc_business_date_store_item` (`business_id`,`consumption_date`,`store_id`,`item_id`),
  CONSTRAINT `inventory_daily_consumptions_business_id_foreign` FOREIGN KEY (`business_id`) REFERENCES `businesses` (`id`) ON DELETE CASCADE,
  CONSTRAINT `inventory_daily_consumptions_item_id_foreign` FOREIGN KEY (`item_id`) REFERENCES `items` (`id`) ON DELETE CASCADE,
  CONSTRAINT `inventory_daily_consumptions_recorded_by_user_id_foreign` FOREIGN KEY (`recorded_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `inventory_daily_consumptions_store_id_foreign` FOREIGN KEY (`store_id`) REFERENCES `stores` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=34825 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

