-- Table structure for table `inventory_order_approvals`
--

DROP TABLE IF EXISTS `inventory_order_approvals`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventory_order_approvals` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `inventory_order_id` bigint unsigned NOT NULL,
  `approver_user_id` bigint unsigned NOT NULL,
  `approval_order` tinyint unsigned NOT NULL,
  `status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `comment` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `acted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `inv_order_approval_order_unique` (`inventory_order_id`,`approval_order`),
  KEY `inventory_order_approvals_approver_user_id_foreign` (`approver_user_id`),
  CONSTRAINT `inventory_order_approvals_approver_user_id_foreign` FOREIGN KEY (`approver_user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `inventory_order_approvals_inventory_order_id_foreign` FOREIGN KEY (`inventory_order_id`) REFERENCES `inventory_orders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
