--
-- Table structure for table `inventory_orders`
--

DROP TABLE IF EXISTS `inventory_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventory_orders` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `business_id` bigint unsigned NOT NULL,
  `store_id` bigint unsigned NOT NULL,
  `order_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'external',
  `source_store_id` bigint unsigned DEFAULT NULL,
  `supplier_id` bigint unsigned DEFAULT NULL,
  `order_number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `current_approval_order` tinyint unsigned DEFAULT NULL,
  `importance_filter` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `group_id` bigint unsigned DEFAULT NULL,
  `subgroup_id` bigint unsigned DEFAULT NULL,
  `item_ids` json DEFAULT NULL,
  `budget_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `budget_value` decimal(14,2) DEFAULT NULL,
  `budget_cap_enforced` tinyint(1) NOT NULL DEFAULT '1',
  `initial_order_total` decimal(14,2) DEFAULT NULL,
  `moving_average_days` smallint unsigned NOT NULL DEFAULT '30',
  `period_of_order_days` decimal(8,2) DEFAULT NULL,
  `safety_stock_days` decimal(8,2) DEFAULT NULL,
  `buffer_stock_days` decimal(8,2) DEFAULT NULL,
  `notification_to_order_days` decimal(8,2) DEFAULT NULL,
  `peak_period_percent` decimal(8,4) DEFAULT '0.0000',
  `peak_consumption_increase_percent` decimal(8,4) DEFAULT '0.0000',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `rfq_document_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rfq_document_original_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by_user_id` bigint unsigned DEFAULT NULL,
  `submitted_by_user_id` bigint unsigned DEFAULT NULL,
  `submitted_at` timestamp NULL DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `rejection_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `inventory_orders_business_id_order_number_unique` (`business_id`,`order_number`),
  KEY `inventory_orders_store_id_foreign` (`store_id`),
  KEY `inventory_orders_created_by_user_id_foreign` (`created_by_user_id`),
  KEY `inventory_orders_group_id_foreign` (`group_id`),
  KEY `inventory_orders_subgroup_id_foreign` (`subgroup_id`),
  KEY `inventory_orders_submitted_by_user_id_foreign` (`submitted_by_user_id`),
  KEY `inventory_orders_supplier_id_foreign` (`supplier_id`),
  KEY `inventory_orders_source_store_id_foreign` (`source_store_id`),
  CONSTRAINT `inventory_orders_business_id_foreign` FOREIGN KEY (`business_id`) REFERENCES `businesses` (`id`) ON DELETE CASCADE,
  CONSTRAINT `inventory_orders_created_by_user_id_foreign` FOREIGN KEY (`created_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `inventory_orders_group_id_foreign` FOREIGN KEY (`group_id`) REFERENCES `groups` (`id`) ON DELETE SET NULL,
  CONSTRAINT `inventory_orders_source_store_id_foreign` FOREIGN KEY (`source_store_id`) REFERENCES `stores` (`id`) ON DELETE SET NULL,
  CONSTRAINT `inventory_orders_store_id_foreign` FOREIGN KEY (`store_id`) REFERENCES `stores` (`id`) ON DELETE CASCADE,
  CONSTRAINT `inventory_orders_subgroup_id_foreign` FOREIGN KEY (`subgroup_id`) REFERENCES `sub_groups` (`id`) ON DELETE SET NULL,
  CONSTRAINT `inventory_orders_submitted_by_user_id_foreign` FOREIGN KEY (`submitted_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `inventory_orders_supplier_id_foreign` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

