--
-- Table structure for table `items`
--

DROP TABLE IF EXISTS `items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `generic_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` enum('service','good','package','bulk') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `importance_category` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `group_id` bigint unsigned DEFAULT NULL,
  `subgroup_id` bigint unsigned DEFAULT NULL,
  `department_id` bigint unsigned DEFAULT NULL,
  `uom_id` bigint unsigned DEFAULT NULL,
  `order_unit_id` bigint unsigned DEFAULT NULL,
  `suom_per_ouom` decimal(14,4) DEFAULT NULL,
  `service_point_id` bigint unsigned DEFAULT NULL,
  `default_price` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0',
  `purchase_price` decimal(14,2) DEFAULT NULL,
  `vat_rate` decimal(5,2) DEFAULT '0.00' COMMENT 'VAT rate as percentage (e.g., 18.00 for 18%)',
  `validity_days` int DEFAULT NULL,
  `max_qty` int DEFAULT '1' COMMENT 'Maximum total combined quantity that can be consumed across all package usages. Only applies to package type items.',
  `hospital_share` tinyint unsigned NOT NULL DEFAULT '100',
  `contractor_account_id` bigint unsigned DEFAULT NULL,
  `business_id` bigint unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `other_names` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `items_uuid_unique` (`uuid`),
  UNIQUE KEY `items_code_unique` (`code`),
  KEY `items_business_id_foreign` (`business_id`),
  KEY `items_order_unit_id_foreign` (`order_unit_id`),
  CONSTRAINT `items_order_unit_id_foreign` FOREIGN KEY (`order_unit_id`) REFERENCES `item_units` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=241 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `items`
--

LOCK TABLES `items` WRITE;
/*!40000 ALTER TABLE `items` DISABLE KEYS */;
