--
-- Table structure for table `service_queues`
--

DROP TABLE IF EXISTS `service_queues`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `service_queues` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `client_id` bigint unsigned NOT NULL,
  `service_point_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `business_id` bigint unsigned NOT NULL,
  `branch_id` bigint unsigned NOT NULL,
  `queue_number` int NOT NULL,
  `status` enum('pending','in_progress','completed','cancelled') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `priority` enum('low','normal','high','urgent') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal',
  `estimated_duration` int DEFAULT NULL,
  `actual_duration` int DEFAULT NULL,
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `started_at` timestamp NULL DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `items` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `total_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `payment_status` enum('pending','paid','partial') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `service_queues_uuid_unique` (`uuid`),
  KEY `service_queues_client_id_foreign` (`client_id`),
  KEY `service_queues_branch_id_foreign` (`branch_id`),
  KEY `service_queues_service_point_id_status_index` (`service_point_id`,`status`),
  KEY `service_queues_business_id_created_at_index` (`business_id`,`created_at`),
  KEY `service_queues_user_id_status_index` (`user_id`,`status`),
  KEY `service_queues_queue_number_service_point_id_created_at_index` (`queue_number`,`service_point_id`,`created_at`),
  CONSTRAINT `service_queues_chk_1` CHECK (json_valid(`items`))
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

