--
-- Table structure for table `withdrawal_requests`
--

DROP TABLE IF EXISTS `withdrawal_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `withdrawal_requests` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `transaction_reference` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `request_type` enum('charge','amount') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `business_id` bigint unsigned NOT NULL,
  `requested_by` bigint unsigned NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `withdrawal_charge` decimal(15,2) NOT NULL DEFAULT '0.00',
  `net_amount` decimal(15,2) NOT NULL,
  `withdrawal_type` enum('regular','express') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'regular',
  `status` enum('pending','business_approved','kashtre_approved','approved','rejected','processing','completed','failed') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `rejection_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `account_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `account_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bank_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mobile_money_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payment_method` enum('bank_transfer','mobile_money') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'mobile_money',
  `business_approvals_count` int NOT NULL DEFAULT '0',
  `kashtre_approvals_count` int NOT NULL DEFAULT '0',
  `required_business_approvals` int NOT NULL DEFAULT '3',
  `required_kashtre_approvals` int NOT NULL DEFAULT '3',
  `current_business_step` int NOT NULL DEFAULT '1',
  `current_kashtre_step` int NOT NULL DEFAULT '1',
  `business_step_1_approvals` int NOT NULL DEFAULT '0',
  `business_step_2_approvals` int NOT NULL DEFAULT '0',
  `business_step_3_approvals` int NOT NULL DEFAULT '0',
  `kashtre_step_1_approvals` int NOT NULL DEFAULT '0',
  `kashtre_step_2_approvals` int NOT NULL DEFAULT '0',
  `kashtre_step_3_approvals` int NOT NULL DEFAULT '0',
  `business_approved_at` timestamp NULL DEFAULT NULL,
  `kashtre_approved_at` timestamp NULL DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `rejected_at` timestamp NULL DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `processed_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `related_request_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `withdrawal_requests_uuid_unique` (`uuid`),
